const searchPullRequests = `-- name: SearchPullRequests :many
SELECT i.id, i.repo_id, i.number, i.kind, i.title, i.body, i.state, i.state_reason, i.locked, i.lock_reason, i.author_id, i.milestone_id, i.comment_count, i.closed_at, i.closed_by, i.edited_at, i.edited_by, i.created_at, i.updated_at FROM issues i
JOIN pull_requests p ON p.issue_id = i.id
WHERE i.repo_id = $1 AND i.kind = 'pull'
  AND (CASE $2::text
         WHEN 'open' THEN i.state = 'open'
         WHEN 'closed' THEN i.state = 'closed'
         WHEN 'merged' THEN p.merged_at IS NOT NULL
         ELSE true END)
  AND ($3::text = '' OR p.base_ref = $3::text)
  AND ($4::text = '' OR p.head_ref = $4::text)
  AND (NOT $5::boolean OR p.head_repo_id = $6::uuid)
  AND (NOT $7::boolean OR i.author_id = $8::uuid)
ORDER BY
  CASE WHEN $9::text = 'updated' THEN i.updated_at END DESC,
  i.number DESC
LIMIT $11 OFFSET $10
`

type SearchPullRequestsParams struct {
	RepoID     uuid.UUID
	State      string
	BaseRef    string
	HeadRef    string
	ByHeadRepo bool
	HeadRepoID uuid.UUID
	ByAuthor   bool
	AuthorID   uuid.UUID
	Sort       string
	Off        int32
	Lim        int32
}

// Pull requests of a repository. state is open, closed (not merged), merged,
// all (” = all). base/head filter on the branch names (” = any).
func (q *Queries) SearchPullRequests(ctx context.Context, arg SearchPullRequestsParams) ([]Issue, error) {
	rows, err := q.db.Query(ctx, searchPullRequests,
		arg.RepoID,
		arg.State,
		arg.BaseRef,
		arg.HeadRef,
		arg.ByHeadRepo,
		arg.HeadRepoID,
		arg.ByAuthor,
		arg.AuthorID,
		arg.Sort,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Issue{}
	for rows.Next() {
		var i Issue
		if err := rows.Scan(
			&i.ID,
			&i.RepoID,
			&i.Number,
			&i.Kind,
			&i.Title,
			&i.Body,
			&i.State,
			&i.StateReason,
			&i.Locked,
			&i.LockReason,
			&i.AuthorID,
			&i.MilestoneID,
			&i.CommentCount,
			&i.ClosedAt,
			&i.ClosedBy,
			&i.EditedAt,
			&i.EditedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

